using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.SceneManagement;
using UnityEngine.UI;
[DefaultExecutionOrder(-1100)]public sealed partial class GridShiftCampaignUI:MonoBehaviour {
 public static GridShiftCampaignUI Instance{get;private set;}public static bool ModalOpen=>Instance!=null&&Instance.root!=null&&Instance.root.activeSelf;public bool IntroSkipped{get;private set;}
 GridShiftDialogueVisibility conversationView;GameObject root;RectTransform panel;TMP_Text title,body;Transform buttons;PlayerMovement locked;bool blocked,visible;CursorLockMode cursor;bool intro;Camera tour;float introAt;Canvas canvas;
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.AfterSceneLoad)]static void Install(){if(Instance==null)new GameObject("GridShiftCampaignUI").AddComponent<GridShiftCampaignUI>();}
 void Awake(){if(Instance!=null){Destroy(gameObject);return;}Instance=this;DontDestroyOnLoad(gameObject);Build();}
 RectTransform Rect(string name,Transform parent,Vector2 size){var go=new GameObject(name,typeof(RectTransform));go.transform.SetParent(parent,false);var r=go.GetComponent<RectTransform>();r.sizeDelta=size;return r;}
 TMP_Text Text(Transform parent,string value,float font,Vector2 size,Vector2 pos){var r=Rect("Label",parent,size);r.anchoredPosition=pos;var t=r.gameObject.AddComponent<TextMeshProUGUI>();t.text=value;t.fontSize=font;t.raycastTarget=false;t.color=Color.white;return t;}
 void Build(){canvas=gameObject.AddComponent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceOverlay;canvas.sortingOrder=875;var scale=gameObject.AddComponent<CanvasScaler>();scale.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scale.referenceResolution=new Vector2(1920,1080);scale.matchWidthOrHeight=.5f;gameObject.AddComponent<GraphicRaycaster>();var overlay=Rect("CampaignDialogue",transform,Vector2.zero);overlay.anchorMin=Vector2.zero;overlay.anchorMax=Vector2.one;overlay.offsetMin=overlay.offsetMax=Vector2.zero;overlay.gameObject.AddComponent<Image>().color=new Color(0,0,0,.58f);root=overlay.gameObject;panel=Rect("Panel",overlay,new Vector2(950,550));GridShiftUITheme.Surface(panel.gameObject.AddComponent<Image>(),"Painel_Menu_Cantos_Amarelos");title=Text(panel,"",32,new Vector2(830,70),new Vector2(0,195));title.color=new Color(1,.82f,.2f);body=Text(panel,"",23,new Vector2(830,240),new Vector2(0,30));var row=Rect("Actions",panel,new Vector2(830,120));row.anchoredPosition=new Vector2(0,-180);var layout=row.gameObject.AddComponent<VerticalLayoutGroup>();layout.spacing=8;layout.childControlHeight=true;layout.childControlWidth=true;layout.childForceExpandHeight=true;buttons=row;GridShiftDialogueStyle.Surface(panel.GetComponent<Image>());GridShiftDialogueStyle.Brand(panel);title.rectTransform.sizeDelta=new Vector2(720,70);title.rectTransform.anchoredPosition=new Vector2(40,195);root.SetActive(false);}
 public void Option(string label,UnityEngine.Events.UnityAction action)=>Button(label,action);
 void Button(string label,UnityEngine.Events.UnityAction action){var r=Rect(label,buttons,new Vector2(800,36));var b=r.gameObject.AddComponent<Button>();r.gameObject.AddComponent<Image>();Text(r,label,20,new Vector2(720,35),Vector2.zero).alignment=TextAlignmentOptions.Center;b.onClick.AddListener(action);GridShiftUITheme.Button(b);}
 public void Open(string heading,string text){Close();EndSocial();locked=Object.FindObjectsByType<PlayerMovement>(FindObjectsSortMode.None).FirstOrDefault(p=>p.gameObject.scene==SceneManager.GetActiveScene());conversationView=new GridShiftDialogueVisibility(locked);blocked=locked!=null&&locked.ControlsBlocked;cursor=Cursor.lockState;visible=Cursor.visible;if(locked!=null)locked.BlockControls(true);Cursor.lockState=CursorLockMode.None;Cursor.visible=true;title.text=heading;body.text=text;GridShiftTutorialGuide.HideForDialogue();root.SetActive(true);foreach(Transform b in buttons){b.gameObject.SetActive(false);Destroy(b.gameObject);}}
 public void Merchant(){GridShiftMentor.Talk();}
 public void Conversation(string heading,string message,string primary,UnityEngine.Events.UnityAction action,string secondary=null,UnityEngine.Events.UnityAction other=null){Open(heading,message);Button(primary,action);if(secondary!=null)Button(secondary,other);Button("Encerrar conversa",Close);}
 public void SetConversationText(string message){body.text=message;}
 public void MerchantContract(){var c=DeliveryManager.Instance.Company;string error;if(c.Missions.First.status==CompanyMissionStatus.Completed){Open("Carlos — Cliente parceiro","Obrigado pela parceria! Acompanhe novos contratos e o crescimento da GridShift no tablet.");Button("Voltar",Close);return;}if(!c.Missions.Talk(false,out error)){Open("Carlos — Comerciante",error);Button("Voltar",Close);return;}Open("Carlos — Comerciante","Bom dia! A VetorLog atende os grandes clientes, mas preciso de uma transportadora para uma entrega local de 5 kg.\n\nVocê escolhe um carro disponível no painel. O pagamento da entrega e o bônus da missão são registrados separadamente.");Button("Aceitar proposta",()=>{if(c.Missions.Talk(true,out var e))Close();else body.text=e;});Button("Consultar detalhes",()=>body.text="Origem: "+DeliveryManager.Instance.Point(c.State.merchantPoint)?.displayName+"\nDestino: "+DeliveryManager.Instance.Point(c.State.deliveryPoint)?.displayName+"\nCarga: 5 kg · Veículo: carro · Bônus da missão: R$ "+c.Balance.firstMissionBonus.ToString("0.00")+"\nVocê recebe a entrega real e confirma a missão uma única vez no tablet.");Button("Recusar por enquanto",Close);}
 public void ShowIntro(){IntroSkipped=false;Open("GRIDSHIFT — DO ZERO AO TOPO","A cidade nunca para.\nTodos os dias, mercadorias precisam chegar aos seus destinos.\n\nA VetorLog domina as grandes rotas. Mas toda transportadora começou com sua primeira entrega.\n\nVocê decidiu construir a GridShift Logistics.");intro=true;introAt=Time.unscaledTime;root.GetComponent<Image>().color=new Color(0,0,0,.25f);panel.anchoredPosition=new Vector2(0,-175);GridShiftUITheme.Art(panel,"GS_Simbolo_Transparente",new Vector2(75,75),new Vector2(360,195));Button("Pular introdução / Começar",()=>IntroSkipped=true);tour=new GameObject("CampaignCityTour").AddComponent<Camera>();tour.depth=50;var point=DeliveryManager.Instance.Point(DeliveryManager.Instance.Company.State.merchantPoint);var at=point!=null?point.Stop:new Vector3(150,0,150);tour.transform.position=at+new Vector3(-20,18,-20);tour.transform.LookAt(at+Vector3.up*2);}
 void Update(){if(!ModalOpen)return;if(intro&&tour!=null){var point=DeliveryManager.Instance.Point(DeliveryManager.Instance.Company.State.merchantPoint);if(point!=null){float t=Time.unscaledTime-introAt;tour.transform.position=point.Stop+new Vector3(-20+Mathf.Sin(t*.1f)*8,18,-20);tour.transform.LookAt(point.Stop+Vector3.up*2);}}if(GridShiftControls.Back&&GridShiftLife.Instance?.Dead!=true){EscapeInput.Consume();GridShiftControls.SuppressFrame();if(intro)IntroSkipped=true;else Close();}}
 public void Close(){EndSocial();if(root==null||!root.activeSelf)return;root.SetActive(false);conversationView?.Restore();conversationView=null;if(locked!=null)locked.BlockControls(blocked);Cursor.lockState=cursor;Cursor.visible=visible;locked=null;if(tour!=null)Destroy(tour.gameObject);tour=null;intro=false;panel.anchoredPosition=Vector2.zero;root.GetComponent<Image>().color=new Color(0,0,0,.58f);}
 void OnDestroy(){Close();if(Instance==this)Instance=null;}
}
